/bin/zsh -lc "python3 - <<'PY'
from pathlib import Path
paths = sorted(Path('.anamnesis/ontology').glob('*.yaml'))
for p in [Path('system_graph.yaml'), Path('.anamnesis/ontology/system_graph.yaml')]:
    if p.exists() and p not in paths:
        paths.append(p)
handoff = Path('.anamnesis/handoff')
print(f'Handoff directory exists: {handoff.is_dir()}')
active = handoff / 'active.md'
if active.exists():
    paths.append(active)
paths.append(Path('docs/cache-policy.md'))
for p in paths:
    print(f'\\n--- {p} ---')
    try:
        print(p.read_text())
    except OSError as e:
        print(f'READ ERROR: {e}')
PY"
